function(container, apiUrl, tables) {
  let calculationResults = [];

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.style.background = 'rgba(40, 167, 69, 0.1)';
    errorDiv.style.borderColor = '#28a745';
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
      errorDiv.style.background = 'rgba(220, 53, 69, 0.1)';
      errorDiv.style.borderColor = '#dc3545';
    }, 3000);
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    const tbody = container.querySelector('#results-tbody');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id || ''}">
        <td>${r.productName || ''}</td>
        <td>${r.productCode || ''}</td>
        <td>${r.currentStock || 0}</td>
        <td>${r.forecastDemand || 0}</td>
        <td>${r.safetyStock || 0}</td>
        <td>${r.reorderPoint || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.recommendedOrder || 0}</td>
        <td>${r.leadTime || 0}日</td>
        <td>${r.calculatedAt || ''}</td>
        <td>
          <button class="action-btn secondary order-btn" data-id="${r.id || ''}">発注</button>
        </td>
      </tr>
    `).join('');
  }

  // 店舗選択肢の初期化
  async function initStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const storeCheckboxes = container.querySelector('#store-checkboxes');

    try {
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        // 単一選択用ドロップダウン
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(s => s.有効フラグ).map(s => 
            `<option value="${s.店舗ID}">${s.店舗名}</option>`
          ).join('');

        // 複数選択用チェックボックス
        storeCheckboxes.innerHTML = stores.filter(s => s.有効フラグ).map(s => `
          <label style="display: flex; align-items: center; gap: 8px;">
            <input type="checkbox" class="store-checkbox" value="${s.店舗ID}">
            <span>${s.店舗名}</span>
          </label>
        `).join('');
      }
    } catch (error) {
      console.error('店舗データの取得に失敗:', error);
    }
  }

  // 発注量計算ロジック
  function calculateOrderQuantity(currentStock, forecastDemand, safetyStock, leadTime, orderCycle) {
    // 発注量 = (予測需要量 × (リードタイム + 発注サイクル) / 発注サイクル) + 安全在庫 - 現在在庫
    const demandDuringLeadTime = forecastDemand * (leadTime + orderCycle) / orderCycle;
    const recommendedOrder = Math.max(0, demandDuringLeadTime + safetyStock - currentStock);
    return Math.ceil(recommendedOrder);
  }

  // バリデーション関数
  function validateInputs() {
    const storeId = container.querySelector('#store-select').value;
    const category = container.querySelector('#category-select').value;
    const periodStart = container.querySelector('#period-start').value;
    const periodEnd = container.querySelector('#period-end').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return false;
    }
    if (!category) {
      showError('商品カテゴリを選択してください');
      return false;
    }
    if (!periodStart || !periodEnd) {
      showError('計算対象期間を設定してください');
      return false;
    }
    if (new Date(periodStart) > new Date(periodEnd)) {
      showError('開始日は終了日より前の日付を設定してください');
      return false;
    }
    return true;
  }

  // 個別商品バリデーション
  function validateProductInputs() {
    const productCode = container.querySelector('#product-code').value;
    const currentStock = parseInt(container.querySelector('#current-stock').value);
    const forecastDemand = parseInt(container.querySelector('#forecast-demand').value);
    const safetyStock = parseInt(container.querySelector('#safety-stock').value);
    const leadTime = parseInt(container.querySelector('#lead-time').value);
    const reorderPoint = container.querySelector('#reorder-point').value;

    if (!productCode) {
      showError('商品コードを入力してください');
      return false;
    }
    if (isNaN(currentStock) || currentStock < 0) {
      showError('現在在庫数は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(forecastDemand) || forecastDemand < 0) {
      showError('予測需要量は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(safetyStock) || safetyStock < 0) {
      showError('安全在庫数は0以上の数値を入力してください');
      return false;
    }
    if (isNaN(leadTime) || leadTime <= 0) {
      showError('リードタイムは1以上の値を入力してください');
      return false;
    }
    if (reorderPoint && (isNaN(parseInt(reorderPoint)) || parseInt(reorderPoint) < 0)) {
      showError('発注点は0以上の数値を入力してください');
      return false;
    }
    return true;
  }

  // 計算実行
  container.querySelector('#btn-calculate').addEventListener('click', async () => {
    if (!validateProductInputs()) return;

    const productCode = container.querySelector('#product-code').value;
    const currentStock = parseInt(container.querySelector('#current-stock').value);
    const forecastDemand = parseInt(container.querySelector('#forecast-demand').value);
    const safetyStock = parseInt(container.querySelector('#safety-stock').value);
    const leadTime = parseInt(container.querySelector('#lead-time').value);
    const orderCycle = parseInt(container.querySelector('#order-cycle').value) || 7;
    const reorderPoint = parseInt(container.querySelector('#reorder-point').value) || 0;

    // 商品情報を取得
    const products = await window.aivicApi.list(2); // 商品マスタ
    const product = products?.find(p => p.商品コード === productCode);

    if (!product) {
      showError('指定された商品コードが見つかりません');
      return;
    }

    const recommendedOrder = calculateOrderQuantity(currentStock, forecastDemand, safetyStock, leadTime, orderCycle);

    const result = {
      id: Date.now().toString(),
      productName: product.商品名,
      productCode: productCode,
      currentStock: currentStock,
      forecastDemand: forecastDemand,
      safetyStock: safetyStock,
      reorderPoint: reorderPoint,
      recommendedOrder: recommendedOrder,
      leadTime: leadTime,
      calculatedAt: new Date().toLocaleString('ja-JP')
    };

    calculationResults.unshift(result);
    renderResults(calculationResults);

    // 需要予測結果表示を更新
    const forecastDisplay = container.querySelector('#forecast-display');
    forecastDisplay.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div>
          <strong>商品名:</strong> ${product.商品名}<br>
          <strong>予測需要:</strong> ${forecastDemand}個
        </div>
        <div>
          <strong>現在在庫:</strong> ${currentStock}個<br>
          <strong>推奨発注量:</strong> <span style="color: var(--primary); font-weight: bold;">${recommendedOrder}個</span>
        </div>
        <div>
          <strong>安全在庫:</strong> ${safetyStock}個<br>
          <strong>リードタイム:</strong> ${leadTime}日
        </div>
      </div>
    `;

    showSuccess('発注量計算が完了しました');
  });

  // 一括計算
  container.querySelector('#btn-bulk-calculate').addEventListener('click', async () => {
    if (!validateInputs()) return;

    const selectedStores = Array.from(container.querySelectorAll('.store-checkbox:checked')).map(cb => cb.value);
    if (selectedStores.length === 0) {
      showError('一括計算する店舗を選択してください');
      return;
    }

    const category = container.querySelector('#category-select').value;

    try {
      const products = await window.aivicApi.list(2); // 商品マスタ
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      const forecasts = await window.aivicApi.list(8); // 需要予測結果

      if (!products || !stores || !forecasts) {
        showError('データの取得に失敗しました');
        return;
      }

      const categoryProducts = products.filter(p => p.商品カテゴリID === category && p.有効フラグ);
      const bulkResults = [];

      selectedStores.forEach(storeId => {
        const store = stores.find(s => s.店舗ID === storeId);

        categoryProducts.forEach(product => {
          const forecast = forecasts.find(f => 
            f.店舗ID === storeId && f.商品ID === product.商品ID
          );

          if (forecast) {
            const currentStock = Math.floor(Math.random() * 100); // 実際は在庫データから取得
            const recommendedOrder = calculateOrderQuantity(
              currentStock,
              forecast.予測数量 || 0,
              product.最小発注数量 || 10,
              product.リードタイム日数 || 3,
              7
            );

            bulkResults.push({
              id: `${storeId}-${product.商品ID}-${Date.now()}`,
              storeName: store?.店舗名,
              productName: product.商品名,
              productCode: product.商品コード,
              currentStock: currentStock,
              forecastDemand: forecast.予測数量 || 0,
              safetyStock: product.最小発注数量 || 10,
              reorderPoint: Math.floor((forecast.予測数量 || 0) * (product.リードタイム日数 || 3) / 7),
              recommendedOrder: recommendedOrder,
              leadTime: product.リードタイム日数 || 3,
              calculatedAt: new Date().toLocaleString('ja-JP')
            });
          }
        });
      });

      calculationResults = bulkResults.concat(calculationResults);
      renderResults(calculationResults);
      showSuccess(`${selectedStores.length}店舗、${bulkResults.length}商品の一括計算が完了しました`);

    } catch (error) {
      showError('一括計算中にエラーが発生しました');
    }
  });

  // 発注データ生成
  container.querySelector('#btn-generate-order').addEventListener('click', async () => {
    if (calculationResults.length === 0) {
      showError('発注データを生成する計算結果がありません');
      return;
    }

    if (!confirm('計算結果に基づいて発注データを生成しますか？')) return;

    try {
      let generatedCount = 0;

      for (const result of calculationResults) {
        if (result.recommendedOrder > 0) {
          const orderData = {
            店舗ID: result.storeId || container.querySelector('#store-select').value,
            商品ID: result.productId,
            発注日: new Date().toISOString(),
            納期予定日: new Date(Date.now() + (result.leadTime * 24 * 60 * 60 * 1000)).toISOString(),
            発注数量: result.recommendedOrder,
            予測数量: result.forecastDemand,
            発注単価: 100, // 実際は商品マスタから取得
            発注金額: result.recommendedOrder * 100,
            発注方法: 'AI自動発注',
            発注ステータス: '発注済',
            仕入先ID: 'supplier-001',
            発注理由: 'AI需要予測による自動発注',
            自動発注フラグ: true,
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString(),
            作成者ID: 'system',
            更新者ID: 'system'
          };

          const saved = await window.aivicApi.save(9, orderData); // 発注データテーブル
          if (saved) generatedCount++;
        }
      }

      showSuccess(`${generatedCount}件の発注データを生成しました`);

      // 発注管理画面に遷移
      setTimeout(() => {
        window.showScreen('scr-1778591852463');
      }, 2000);

    } catch (error) {
      showError('発注データの生成中にエラーが発生しました');
    }
  });

  // 行レベル操作（発注ボタン）
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const resultId = orderBtn.dataset.id;
      const result = calculationResults.find(r => r.id === resultId);

      if (result && confirm(`${result.productName}を${result.recommendedOrder}個発注しますか？`)) {
        // 発注実行画面に遷移
        window.showScreen('scr-1778591960771');
      }
    }
  });

  // 初期化
  initStoreOptions();
  renderResults([]);

  // 今日の日付を初期値として設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#period-start').value = today;
  container.querySelector('#period-end').value = today;
}
